inline xcb_connection_t*connection(Display*d){XFlush(d);return XGetXCBConnection(d);}
inline int error(xcb_connection_t*c,xcb_void_cookie_t cookie){auto*e=xcb_request_check(c,cookie);if(!e)return Success;const int code=e->error_code;std::free(e);return code;}
inline int changeProperty(Display*d,::Window w,Atom key,Atom type,int format,int mode,const unsigned char*data,int count){if(count<0||(format!=8&&format!=16&&format!=32))return BadValue;auto*c=connection(d);std::vector<std::uint32_t>words;if(format==32){const auto*source=reinterpret_cast<const unsigned long*>(data);words.resize(std::size_t(count));for(int i=0;i<count;++i)words[i]=std::uint32_t(source[i]);data=reinterpret_cast<const unsigned char*>(words.data());}return error(c,xcb_change_property_checked(c,std::uint8_t(mode),xcb_window_t(w),xcb_atom_t(key),xcb_atom_t(type),std::uint8_t(format),std::uint32_t(count),data));}
inline int deleteProperty(Display*d,::Window w,Atom key){auto*c=connection(d);return error(c,xcb_delete_property_checked(c,xcb_window_t(w),xcb_atom_t(key)));}
inline int getWindowProperty(Display*d,::Window w,Atom key,long offset,long length,Bool remove,Atom type,Atom*actual,int*format,unsigned long*count,unsigned long*remaining,unsigned char**data){*actual=0;*format=0;*count=*remaining=0;*data=nullptr;if(offset<0||length<0||std::uint64_t(offset)>UINT32_MAX)return BadValue;auto*c=connection(d);xcb_generic_error_t*failure{};auto*reply=xcb_get_property_reply(c,xcb_get_property(c,remove,xcb_window_t(w),xcb_atom_t(key),xcb_atom_t(type),std::uint32_t(offset),std::uint32_t(std::min<std::uint64_t>(UINT32_MAX,std::uint64_t(length)))),&failure);if(failure){const auto code=failure->error_code;std::free(failure);std::free(reply);return code;}if(!reply)return BadWindow;*actual=reply->type;*format=reply->format;*count=reply->value_len;*remaining=reply->bytes_after;const auto bytes=reply->format==32?std::size_t(reply->value_len)*sizeof(unsigned long):std::size_t(xcb_get_property_value_length(reply));auto*result=static_cast<unsigned char*>(std::calloc(bytes+1,1));if(!result){std::free(reply);return BadAlloc;}if(reply->format==32){const auto*source=static_cast<const std::uint32_t*>(xcb_get_property_value(reply));auto*dest=reinterpret_cast<unsigned long*>(result);for(std::size_t i=0;i<reply->value_len;++i)dest[i]=source[i];}else if(bytes)std::memcpy(result,xcb_get_property_value(reply),bytes);*data=result;std::free(reply);return Success;}
inline int selectInput(Display*d,::Window w,long mask){auto*c=connection(d);const std::uint32_t value=std::uint32_t(mask);return error(c,xcb_change_window_attributes_checked(c,xcb_window_t(w),XCB_CW_EVENT_MASK,&value));}
inline ::Window createWindow(Display*d,::Window parent,unsigned width,unsigned height,bool inputOnly=false){if(!width||!height||width>UINT16_MAX||height>UINT16_MAX)return None;auto*c=connection(d);const auto id=xcb_generate_id(c);const std::uint32_t values[]{0,0};const auto mask=inputOnly?std::uint32_t(XCB_CW_OVERRIDE_REDIRECT):std::uint32_t(XCB_CW_BACK_PIXEL|XCB_CW_BORDER_PIXEL);const std::uint32_t overrideRedirect=1;if(error(c,xcb_create_window_checked(c,XCB_COPY_FROM_PARENT,id,xcb_window_t(parent),0,0,std::uint16_t(width),std::uint16_t(height),0,inputOnly?XCB_WINDOW_CLASS_INPUT_ONLY:XCB_WINDOW_CLASS_INPUT_OUTPUT,XCB_COPY_FROM_PARENT,mask,inputOnly?&overrideRedirect:values))!=Success)return None;return id;}
