inline int moveWindow(Display*d,::Window w,int x,int y){const std::uint32_t values[]{std::uint32_t(x),std::uint32_t(y)};return configure(d,w,XCB_CONFIG_WINDOW_X|XCB_CONFIG_WINDOW_Y,values)?Success:BadWindow;}
