inline Bool attributes(Display*d,::Window w,XWindowAttributes*out){auto*c=connection(d);xcb_generic_error_t*failure{};auto*reply=xcb_get_window_attributes_reply(c,xcb_get_window_attributes(c,xcb_window_t(w)),&failure);if(failure||!reply){std::free(failure);std::free(reply);return False;}auto*geometry=xcb_get_geometry_reply(c,xcb_get_geometry(c,xcb_drawable_t(w)),&failure);if(failure||!geometry){std::free(failure);std::free(reply);std::free(geometry);return False;}XVisualInfo query{};query.visualid=reply->visual;int count{};auto*visuals=XGetVisualInfo(d,VisualIDMask,&query,&count);std::memset(out,0,sizeof *out);if(visuals&&count){out->visual=visuals[0].visual;out->depth=geometry->depth;out->map_state=reply->map_state;out->x=geometry->x;out->y=geometry->y;out->width=geometry->width;out->height=geometry->height;out->your_event_mask=reply->your_event_mask;}if(visuals)XFree(visuals);std::free(geometry);std::free(reply);return out->visual?True:False;}
inline std::uint32_t createGC(Display*d,::Window w){auto*c=connection(d);const auto id=xcb_generate_id(c);return error(c,xcb_create_gc_checked(c,id,xcb_drawable_t(w),0,nullptr))==Success?id:0;}
