inline int setInputFocus(Display*d,::Window w,int revert,Time when){auto*c=connection(d);return error(c,xcb_set_input_focus_checked(c,std::uint8_t(revert),xcb_window_t(w),xcb_timestamp_t(when)));}
inline Cursor createCursor(Display*d,unsigned shape){auto*c=connection(d);const auto font=xcb_generate_id(c),cursor=xcb_generate_id(c);const char name[]="cursor";if(error(c,xcb_open_font_checked(c,font,6,name))!=Success)return 0;const auto status=error(c,xcb_create_glyph_cursor_checked(c,cursor,font,font,std::uint16_t(shape),std::uint16_t(shape+1),0,0,0,65535,65535,65535));error(c,xcb_close_font_checked(c,font));return status==Success?Cursor(cursor):0;}
inline int defineCursor(Display*d,::Window w,Cursor cursor){auto*c=connection(d);const std::uint32_t value=std::uint32_t(cursor);return error(c,xcb_change_window_attributes_checked(c,xcb_window_t(w),XCB_CW_CURSOR,&value));}
