inline int grabPointer(Display*d,::Window w,Bool owner,unsigned mask,int pointerMode,int keyboardMode,::Window confine,Cursor cursor,Time when){auto*c=connection(d);xcb_generic_error_t*failure{};auto*reply=xcb_grab_pointer_reply(c,xcb_grab_pointer(c,owner,xcb_window_t(w),std::uint16_t(mask),std::uint8_t(pointerMode),std::uint8_t(keyboardMode),xcb_window_t(confine),xcb_cursor_t(cursor),xcb_timestamp_t(when)),&failure);const int result=failure||!reply?GrabNotViewable:reply->status;std::free(reply);std::free(failure);return result;}
inline int ungrabPointer(Display*d,Time when){auto*c=connection(d);return error(c,xcb_ungrab_pointer_checked(c,xcb_timestamp_t(when)));}
inline Bool queryPointer(Display*d,::Window w,::Window*root,::Window*child,int*rootX,int*rootY,int*x,int*y,unsigned*mask){auto*c=connection(d);xcb_generic_error_t*failure{};auto*r=xcb_query_pointer_reply(c,xcb_query_pointer(c,xcb_window_t(w)),&failure);if(failure||!r){std::free(failure);std::free(r);return False;}*root=r->root;*child=r->child;*rootX=r->root_x;*rootY=r->root_y;*x=r->win_x;*y=r->win_y;*mask=r->mask;const bool same=r->same_screen;std::free(r);return same;}
inline Bool queryTree(Display*d,::Window w,::Window*root,::Window*parent,::Window**children,unsigned*count){
    *root=*parent=None;*children=nullptr;*count=0;
    auto*c=connection(d);xcb_generic_error_t*failure{};
    auto*r=xcb_query_tree_reply(c,xcb_query_tree(c,xcb_window_t(w)),&failure);
    if(failure||!r){std::free(failure);std::free(r);return False;}
    const auto n=unsigned(xcb_query_tree_children_length(r));
    auto*owned=n?static_cast<::Window*>(std::calloc(n,sizeof(::Window))):nullptr;
    if(n&&!owned){std::free(r);return False;}
    const auto*source=xcb_query_tree_children(r);for(unsigned i=0;i<n;++i)owned[i]=source[i];
    *root=r->root;*parent=r->parent;*children=owned;*count=n;std::free(r);return True;
}
inline Bool translateCoordinates(Display*d,::Window from,::Window to,int x,int y,int*dx,int*dy,::Window*child){auto*c=connection(d);xcb_generic_error_t*failure{};auto*r=xcb_translate_coordinates_reply(c,xcb_translate_coordinates(c,xcb_window_t(from),xcb_window_t(to),std::int16_t(x),std::int16_t(y)),&failure);if(failure||!r){std::free(r);std::free(failure);return False;}*dx=r->dst_x;*dy=r->dst_y;*child=r->child;const bool same=r->same_screen;std::free(r);return same;}
