inline int sendEvent(Display*d,::Window destination,Bool propagate,long mask,const XEvent*event){auto*c=connection(d);std::array<char,32>bytes{};
 if(event->type==ClientMessage){xcb_client_message_event_t value{};value.response_type=XCB_CLIENT_MESSAGE;value.format=std::uint8_t(event->xclient.format);value.window=xcb_window_t(event->xclient.window);value.type=xcb_atom_t(event->xclient.message_type);if(value.format==32)for(int i=0;i<5;++i)value.data.data32[i]=std::uint32_t(event->xclient.data.l[i]);else std::memcpy(value.data.data8,event->xclient.data.b,20);static_assert(sizeof value<=32);std::memcpy(bytes.data(),&value,sizeof value);}
 else if(event->type==SelectionNotify){xcb_selection_notify_event_t value{};value.response_type=XCB_SELECTION_NOTIFY;value.requestor=xcb_window_t(event->xselection.requestor);value.selection=xcb_atom_t(event->xselection.selection);value.target=xcb_atom_t(event->xselection.target);value.property=xcb_atom_t(event->xselection.property);value.time=xcb_timestamp_t(event->xselection.time);static_assert(sizeof value<=32);std::memcpy(bytes.data(),&value,sizeof value);}
 else if(event->type==UnmapNotify){xcb_unmap_notify_event_t value{};value.response_type=XCB_UNMAP_NOTIFY;value.event=xcb_window_t(event->xunmap.event);value.window=xcb_window_t(event->xunmap.window);value.from_configure=event->xunmap.from_configure;static_assert(sizeof value<=32);std::memcpy(bytes.data(),&value,sizeof value);}
 else if(event->type==KeyPress||event->type==KeyRelease){const auto&key=event->xkey;xcb_key_press_event_t value{};value.response_type=event->type==KeyPress?XCB_KEY_PRESS:XCB_KEY_RELEASE;value.detail=std::uint8_t(key.keycode);value.time=xcb_timestamp_t(key.time);value.root=xcb_window_t(key.root);value.event=xcb_window_t(key.window);value.child=xcb_window_t(key.subwindow);value.root_x=std::int16_t(key.x_root);value.root_y=std::int16_t(key.y_root);value.event_x=std::int16_t(key.x);value.event_y=std::int16_t(key.y);value.state=std::uint16_t(key.state);value.same_screen=key.same_screen;static_assert(sizeof value<=32);std::memcpy(bytes.data(),&value,sizeof value);}else return False;
 return error(c,xcb_send_event_checked(c,propagate,xcb_window_t(destination),std::uint32_t(mask),bytes.data()))==Success;
}
inline int withdrawWindow(Display*d,::Window w,int screen){unmapWindow(d,w);XEvent event{};event.xunmap.type=UnmapNotify;event.xunmap.event=RootWindow(d,screen);event.xunmap.window=w;return sendEvent(d,RootWindow(d,screen),False,SubstructureRedirectMask|SubstructureNotifyMask,&event);}
inline int storeName(Display*d,::Window w,const char*text){const auto length=std::strlen(text);if(length>INT_MAX)return 0;const auto utf8=XInternAtom(d,"UTF8_STRING",False),name=XInternAtom(d,"_NET_WM_NAME",False);changeProperty(d,w,name,utf8,8,PropModeReplace,reinterpret_cast<const unsigned char*>(text),int(length));return changeProperty(d,w,XA_WM_NAME,XA_STRING,8,PropModeReplace,reinterpret_cast<const unsigned char*>(text),int(length));}
