inline int sizeHints(Display*d,::Window w,XSizeHints*hints){const unsigned long values[]{static_cast<unsigned long>(hints->flags),static_cast<unsigned long>(hints->x),static_cast<unsigned long>(hints->y),static_cast<unsigned long>(hints->width),static_cast<unsigned long>(hints->height),static_cast<unsigned long>(hints->min_width),static_cast<unsigned long>(hints->min_height),static_cast<unsigned long>(hints->max_width),static_cast<unsigned long>(hints->max_height),static_cast<unsigned long>(hints->width_inc),static_cast<unsigned long>(hints->height_inc),static_cast<unsigned long>(hints->min_aspect.x),static_cast<unsigned long>(hints->min_aspect.y),static_cast<unsigned long>(hints->max_aspect.x),static_cast<unsigned long>(hints->max_aspect.y),static_cast<unsigned long>(hints->base_width),static_cast<unsigned long>(hints->base_height),static_cast<unsigned long>(hints->win_gravity)};return changeProperty(d,w,XA_WM_NORMAL_HINTS,XA_WM_SIZE_HINTS,32,PropModeReplace,reinterpret_cast<const unsigned char*>(values),18);}
inline bool putImage(Display*d,::Window w,std::uint32_t gc,XImage*image){auto*c=connection(d);std::uint32_t pad=32;for(auto i=xcb_setup_pixmap_formats_iterator(xcb_get_setup(c));i.rem;xcb_format_next(&i))if(i.data->depth==image->depth){pad=i.data->scanline_pad;break;}const auto stride=((std::uint64_t(image->width)*image->bits_per_pixel+pad-1)/pad)*pad/8;const auto maximum=std::uint64_t(xcb_get_maximum_request_length(c))*4;if(maximum<=64||stride>maximum-64)return false;const auto rows=std::max<std::uint64_t>(1,std::min<std::uint64_t>(UINT16_MAX,(maximum-64)/stride));thread_local std::vector<xcb_void_cookie_t>requests;thread_local std::vector<unsigned char>packed;requests.clear();const auto needed=(std::uint64_t(image->height)+rows-1)/rows;requests.reserve(std::size_t(needed));for(int at=0;at<image->height;){const auto count=unsigned(std::min<std::uint64_t>(rows,unsigned(image->height-at)));const char*data=image->data+std::size_t(at)*image->bytes_per_line;if(stride!=std::uint64_t(image->bytes_per_line)){packed.resize(std::size_t(stride)*count);for(unsigned y=0;y<count;++y)std::memcpy(packed.data()+y*stride,data+std::size_t(y)*image->bytes_per_line,std::size_t(stride));data=reinterpret_cast<const char*>(packed.data());}requests.push_back(xcb_put_image_checked(c,XCB_IMAGE_FORMAT_Z_PIXMAP,xcb_drawable_t(w),gc,std::uint16_t(image->width),std::uint16_t(count),0,std::int16_t(at),0,std::uint8_t(image->depth),std::uint32_t(stride*count),reinterpret_cast<const std::uint8_t*>(data)));at+=int(count);}bool ok=true;for(auto request:requests)ok=(error(c,request)==Success)&&ok;return ok;}
inline unsigned xiRequest(Display*d,std::uint8_t opcode,void*header,std::size_t length,const void*data,std::size_t bytes,bool isVoid){static xcb_extension_t extension{"XInputExtension",0};auto*c=connection(d);const xcb_protocol_request_t request{4,&extension,opcode,std::uint8_t(isVoid)};iovec parts[6]{};parts[2]={header,length};parts[3]={nullptr,(-length)&3};parts[4]={const_cast<void*>(data),bytes};parts[5]={nullptr,(-bytes)&3};return xcb_send_request(c,XCB_REQUEST_CHECKED,parts+2,&request);}
inline bool xiSelect(Display*d,::Window w,int device,std::span<const unsigned char>mask){const auto units=(mask.size()+3)/4;if(units>UINT16_MAX)return false;std::vector<std::uint32_t>payload(units+1);auto*header=reinterpret_cast<std::uint16_t*>(payload.data());header[0]=std::uint16_t(device);header[1]=std::uint16_t(units);if(!mask.empty())std::memcpy(payload.data()+1,mask.data(),mask.size());xXISelectEventsReq request{};request.win=std::uint32_t(w);request.num_masks=1;const auto sequence=xiRequest(d,X_XISelectEvents,&request,sizeof request,payload.data(),payload.size()*4,true);return error(connection(d),{sequence})==Success;}
inline int xiGrab(Display*d,int device,::Window w,Time when,std::span<const unsigned char>mask){const auto units=(mask.size()+3)/4;if(units>UINT16_MAX)return GrabNotViewable;std::vector<std::uint32_t>payload(units);if(!mask.empty())std::memcpy(payload.data(),mask.data(),mask.size());xXIGrabDeviceReq request{};request.grab_window=std::uint32_t(w);request.time=std::uint32_t(when);request.deviceid=std::uint16_t(device);request.grab_mode=GrabModeAsync;request.paired_device_mode=GrabModeAsync;request.mask_len=std::uint16_t(units);const auto sequence=xiRequest(d,X_XIGrabDevice,&request,sizeof request,payload.data(),payload.size()*4,false);xcb_generic_error_t*failure{};auto*reply=static_cast<xXIGrabDeviceReply*>(xcb_wait_for_reply(connection(d),sequence,&failure));const int result=failure||!reply?GrabNotViewable:reply->status;std::free(reply);std::free(failure);return result;}
